 public sealed partial class Controller {
  bool liveReady,liveSaving,styleReady,rescanAfterSettings;DispatcherTimer liveTimer;Button downloadButton;CheckBox linkedSwitch,closePrompt;bool startupAuto,startupAdmin;
  void Setup100(){NativeBackdrop.Attach(w);SetupAssociations();Click("ManageNamesButton",ManageNames);linkedSwitch=Get<CheckBox>("LinkProfilesInput");closePrompt=Get<CheckBox>("CloseWindowPromptInput");UpdateLinkedSwitch();closePrompt.IsChecked=Setting("closeWindowPrompt",true);
   startupAuto=Get<CheckBox>("AutoStartInput").IsChecked==true;startupAdmin=Get<CheckBox>("RunAsAdminInput").IsChecked==true;
   Get<ComboBox>("WindowStyleInput").SelectedIndex=WindowStylePreference.IndexFromStored((int)Number("windowStyle",0,0,3));Get<TextBox>("GradientStart").Text=db.Get("gradientStart","#182433");Get<TextBox>("GradientEnd").Text=db.Get("gradientEnd","#314D64");styleReady=true;
   Click("GradientStartPick",()=>PickGradient("GradientStart"));Click("GradientEndPick",()=>PickGradient("GradientEnd"));
   Get<ComboBox>("WindowStyleInput").SelectionChanged+=delegate{PreviewAppearance();};foreach(string n in new[]{"GradientStart","GradientEnd"})Get<TextBox>(n).TextChanged+=delegate{ApplyWindowStyle();ScheduleLiveSettings();};
   liveTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(220)};liveTimer.Tick+=delegate{liveTimer.Stop();SaveLiveSettings();};
   foreach(string n in new[]{"ConfirmCloseInput","ConfirmHideInput","ConfirmForceInput","ShowCandidates","MinimizeToTray","LaunchHidden","AutoStartInput","RunAsAdminInput","AutoCheckUpdateInput","LinkProfilesInput","CloseWindowPromptInput"}){var c=Get<CheckBox>(n);c.Checked+=delegate{ScheduleLiveSettings();};c.Unchecked+=delegate{ScheduleLiveSettings();};}
