  void ScheduleLiveSettings(){if(!liveReady||initializing||liveSaving)return;liveTimer.Stop();liveTimer.Start();}
  void SaveLiveSettings(){if(!liveReady||initializing||liveSaving)return;liveTimer.Stop();liveSaving=true;bool priorCandidates=Setting("candidates",false);try{SaveSettings();if(priorCandidates!=Setting("candidates",false)&&!demo){rescanAfterSettings=true;w.Dispatcher.BeginInvoke(new Action(RefreshLiveRecognition));}startupAuto=Get<CheckBox>("AutoStartInput").IsChecked==true;startupAdmin=Get<CheckBox>("RunAsAdminInput").IsChecked==true;Status("设置已即时生效并自动保存");}catch(Exception ex){Get<CheckBox>("AutoStartInput").IsChecked=startupAuto;Get<CheckBox>("RunAsAdminInput").IsChecked=startupAdmin;editClose=closeKey;editRestore=restoreKey;Get<TextBox>("CloseHotkeyInput").Text=closeKey.ToString();Get<TextBox>("RestoreHotkeyInput").Text=restoreKey.ToString();Error(new InvalidOperationException("设置未能生效，失败项已还原："+ex.Message,ex));}finally{liveSaving=false;}}
  void RefreshLiveRecognition(){if(!rescanAfterSettings||busy||demo)return;rescanAfterSettings=false;Refresh();}
  void UpdateLinkedSwitch(){var toggle=Get<CheckBox>("LinkProfilesInput");if(toggle==null)return;bool old=liveSaving;liveSaving=true;try{toggle.IsChecked=db.LinkedProfilesEnabled;toggle.IsEnabled=!db.HasActiveAssociations;toggle.ToolTip=db.HasActiveAssociations?"有关联启动规则生效，关联配置自动启用":null;}finally{liveSaving=old;}}
  void RefreshProfileLinks(){var host=Get<StackPanel>("ProfileLinksHost");if(host==null)return;host.Children.Clear();var closes=db.ListSets("profile_close");if(closes.Count==0){host.Children.Add(FeatureUi.Label("暂无关闭配置，可在当前程序页保存配置",true));return;}foreach(var close in closes){long id=close.Id;var grid=new Grid{Margin=new Thickness(0,12,0,8)};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});var label=FeatureUi.Label(close.Name,false);label.VerticalAlignment=VerticalAlignment.Center;grid.Children.Add(label);var options=db.ListSets("profile_restore");var none=new SavedSet{Id=0,Name="不关联"};options.Insert(0,none);var combo=new ComboBox{ItemsSource=options,Margin=new Thickness(12,0,0,0)};combo.SelectedItem=options.FirstOrDefault(x=>x.Id==db.LinkedRestoreProfile(id))??none;combo.SelectionChanged+=delegate{var restore=combo.SelectedItem as SavedSet;if(restore==null)return;Guard(delegate{if(restore.Id==0)db.Execute("DELETE FROM profile_links WHERE close_id=?",id.ToString());else db.LinkProfiles(id,restore.Id);Status("配置关联已更新");});};Grid.SetColumn(combo,1);grid.Children.Add(combo);host.Children.Add(grid);}}
  void RememberLinkedRestore(){if(!db.LinkedProfilesEnabled){pendingRestoreProfile=0;return;}var selected=Get<ComboBox>("CloseProfileCombo").SelectedItem as SavedSet;pendingRestoreProfile=selected==null?0:db.LinkedRestoreProfile(selected.Id);}
  void ApplyPendingRestore(){if(pendingRestoreProfile==0)return;long id=pendingRestoreProfile;pendingRestoreProfile=0;loadingCollections=true;try{var combo=Get<ComboBox>("RestoreProfileCombo");combo.SelectedItem=combo.Items.Cast<SavedSet>().FirstOrDefault(x=>x.Id==id);}finally{loadingCollections=false;}if(Get<ComboBox>("RestoreProfileCombo").SelectedItem!=null)ApplyProfile("restore");}
  void HandleMainClose(object sender,CancelEventArgs e){if(exiting)return;e.Cancel=true;if(busy){Status("操作仍在进行中，完成后可退出；现在可最小化到托盘");w.Hide();return;}if(liveTimer!=null&&liveTimer.IsEnabled)SaveLiveSettings();bool minimize=Setting("closeWindowMinimize",true);if(Setting("closeWindowPrompt",true)){
    var d=CloseWindowDialog.Build(w);var choice=(CloseWindowChoice)d.Tag;d.ShowDialog();if(!choice.Minimize.HasValue)return;minimize=choice.Minimize.Value;db.Set("closeWindowMinimize",minimize?"1":"0");if(choice.Suppress.IsChecked==true){db.Set("closeWindowPrompt","0");if(closePrompt!=null)closePrompt.IsChecked=false;}
   }if(minimize)w.Hide();else{exiting=true;w.Dispatcher.BeginInvoke(new Action(Exit));}}
  void PickGradient(string input){using(var picker=new System.Windows.Forms.ColorDialog{FullOpen=true}){Color color;if(TryColor(Get<TextBox>(input).Text,out color))picker.Color=System.Drawing.Color.FromArgb(color.R,color.G,color.B);var helper=new System.Windows.Forms.NativeWindow();helper.AssignHandle(new System.Windows.Interop.WindowInteropHelper(w).Handle);try{if(picker.ShowDialog(helper)==System.Windows.Forms.DialogResult.OK)Get<TextBox>(input).Text=String.Format("#{0:X2}{1:X2}{2:X2}",picker.Color.R,picker.Color.G,picker.Color.B);}finally{helper.ReleaseHandle();}}}
  static bool TryColor(string input,out Color color){color=Colors.Transparent;try{if(!System.Text.RegularExpressions.Regex.IsMatch(input??"","^#[0-9a-fA-F]{6}$"))return false;color=(Color)ColorConverter.ConvertFromString(input);return true;}catch{return false;}}
  static double Contrast(Color a,Color b){Func<byte,double> channel=value=>{double x=value/255.0;return x<=.04045?x/12.92:Math.Pow((x+.055)/1.055,2.4);};Func<Color,double> light=c=>.2126*channel(c.R)+.7152*channel(c.G)+.0722*channel(c.B);double x1=light(a),x2=light(b);return (Math.Max(x1,x2)+.05)/(Math.Min(x1,x2)+.05);}
  void ApplyWindowStyle(){if(!styleReady)return;var input=Get<ComboBox>("WindowStyleInput");bool competing=Get<ComboBox>("WindowTintInput").SelectedIndex>0||!String.IsNullOrWhiteSpace(Get<TextBox>("BackgroundPath").Text);input.IsEnabled=!competing;int style=competing?0:WindowStylePreference.StoredFromIndex(input.SelectedIndex);Get<ComboBox>("WindowTintInput").IsEnabled=style==0;Get<Button>("ChooseBackgroundButton").IsEnabled=style==0;Get<StackPanel>("GradientOptions").Visibility=style==3?Visibility.Visible:Visibility.Collapsed;
   if(style==3){Color a,b;if(!TryColor(Get<TextBox>("GradientStart").Text,out a)||!TryColor(Get<TextBox>("GradientEnd").Text,out b)){Status("渐变色号需为 #RRGGBB，输入完成后自动生效");return;}bool dark=ThemeManager.IsDark(Get<ComboBox>("ThemeInput").SelectedIndex.ToString());var baseColor=(Color)ColorConverter.ConvertFromString(dark?"#151B1A":"#F3F6F5");var text=((SolidColorBrush)w.Resources["Text"]).Color;var muted=((SolidColorBrush)w.Resources["Muted"]).Color;double amount=.42;while(amount>.02&&(Contrast(ThemeManager.Blend(a,baseColor,amount),text)<4.5||Contrast(ThemeManager.Blend(a,baseColor,amount),muted)<4.5||Contrast(ThemeManager.Blend(b,baseColor,amount),text)<4.5||Contrast(ThemeManager.Blend(b,baseColor,amount),muted)<4.5))amount-=.02;a=ThemeManager.Blend(a,baseColor,amount);b=ThemeManager.Blend(b,baseColor,amount);var gradient=new LinearGradientBrush(a,b,35);gradient.Freeze();w.Resources["Canvas"]=gradient;w.Resources["Sidebar"]=gradient;}
   bool glass=style==1;Get<TextBlock>("StyleConflictNote").Text=UiLanguage.Text(glass?"本样式对GPU性能与占用较高 推荐使用默认样式":"窗口样式与窗口背景主题色、自定义背景图片互斥；恢复默认后可切换");w.Resources["GlassEnabled"]=glass;Get<Border>("BackgroundVeil").Opacity=glass?0:.55;Get<TextBlock>("GlassSystemNote").Visibility=Visibility.Collapsed;
   if(glass){foreach(string key in new[]{"Canvas","Sidebar","Surface","Subtle","Hover"}){var original=w.Resources[key] as SolidColorBrush;if(original==null)continue;Color tint=original.Color;tint.A=(byte)(key=="Canvas"?30:key=="Sidebar"?55:key=="Surface"?95:70);var brush=new SolidColorBrush(tint);brush.Freeze();w.Resources[key]=brush;}w.Resources["Muted"]=ThemeManager.Brush(ThemeManager.IsDark(Get<ComboBox>("ThemeInput").SelectedIndex.ToString())?"#DCE8E0":"#293C33");}
   NativeBackdrop.ApplyAll(w,glass);
  }
 }
 internal static class WindowStylePreference {
  // Keep stored IDs stable: old 2 (acrylic) becomes glass; gradient remains 3.
  internal static int IndexFromStored(int value){return value==3?2:value==1||value==2?1:0;}
  internal static int StoredFromIndex(int value){return value==2?3:value==1?1:0;}
 }
 internal static class NativeBackdrop {
  [StructLayout(LayoutKind.Sequential)]struct Accent {public int State,Flags,Color,Animation;}
  [StructLayout(LayoutKind.Sequential)]struct Data {public int Attribute;public IntPtr Pointer;public int Size;}
  [DllImport("user32.dll")]static extern int SetWindowCompositionAttribute(IntPtr window,ref Data data);
  [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr hwnd,int attribute,ref int value,int size);
  internal static bool SystemTransparencyEnabled(){try{using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"))return Convert.ToInt32(key==null?1:key.GetValue("EnableTransparency",1))!=0;}catch{return true;}}
  internal static bool Enabled(Window w){return w.Resources.Contains("GlassEnabled")&&w.Resources["GlassEnabled"] is bool&&(bool)w.Resources["GlassEnabled"];}
  internal static void Attach(Window w){w.SourceInitialized+=delegate{Apply(w,Enabled(w));};}
  internal static void ApplyAll(Window owner,bool glass){Apply(owner,glass);if(Application.Current!=null)foreach(Window child in Application.Current.Windows)if(child!=owner&&Object.ReferenceEquals(child.Resources,owner.Resources))Apply(child,glass);}
  internal static void Apply(Window window,bool glass){
   var handle=new System.Windows.Interop.WindowInteropHelper(window).Handle;if(handle==IntPtr.Zero)return;
   // Layered windows keep rounded-edge pixels truly transparent, not black.
   if(window.AllowsTransparency){DesktopGlass.Set(window,glass);Chrome.Round(window,Chrome.Radius);return;}
   var chrome=System.Windows.Shell.WindowChrome.GetWindowChrome(window);if(chrome!=null)chrome.GlassFrameThickness=new Thickness(0);
   var source=System.Windows.Interop.HwndSource.FromHwnd(handle);if(source!=null&&source.CompositionTarget!=null)source.CompositionTarget.BackgroundColor=Colors.Transparent;
   try{int backdrop=1;DwmSetWindowAttribute(handle,38,ref backdrop,4);int dark=((SolidColorBrush)window.Resources["Text"]).Color.R>128?1:0;DwmSetWindowAttribute(handle,20,ref dark,4);int round=1;DwmSetWindowAttribute(handle,33,ref round,4);}catch(EntryPointNotFoundException){}
   // Native blur is a compatibility fallback. The live texture does not depend on it.
   var accent=new Accent{State=glass?3:0,Flags=0,Color=0};IntPtr pointer=Marshal.AllocHGlobal(Marshal.SizeOf(accent));try{Marshal.StructureToPtr(accent,pointer,false);var data=new Data{Attribute=19,Pointer=pointer,Size=Marshal.SizeOf(accent)};SetWindowCompositionAttribute(handle,ref data);}catch(EntryPointNotFoundException){}finally{Marshal.FreeHGlobal(pointer);}
   DesktopGlass.Set(window,glass);Chrome.Round(window,Chrome.Radius);
  }
 }
